<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\UserProfileWebsiteUrlVO;

trait UserProfileWebsiteUrlAccessor
{
    private ?UserProfileWebsiteUrlVO $_websiteUrl = null;
    public function getWebsiteUrl(): ?string
    {
        return $this->_websiteUrl?->value();
    }
    public function websiteUrl(): ?UserProfileWebsiteUrlVO
    {
        return $this->_websiteUrl;
    }
    public function isWebsiteUrlChanged(?self $original = null): bool
    {
        return null !== $this->_websiteUrl && !$this->_websiteUrl->equals($original?->_websiteUrl);
    }
    public function withWebsiteUrl(UserProfileWebsiteUrlVO|string|null $websiteUrl): self
    {
        $copy = clone $this;
        $copy->_websiteUrl = UserProfileWebsiteUrlVO::from($websiteUrl);
        return $copy;
    }
}
